import { createCharacterLifeSession,createNpcWorldSession,DEFAULT_PLAYER_DRAFT } from '@haven/core';
import { createMemoryGameStore,recordsToSession,sessionToRecords,GAME_DB,type GameStore,type StoredRecord,deserializeCharacterLifeSave,serializeCharacterLifeSave } from '@haven/persistence';
import { readFileSync } from 'node:fs';
import { afterEach,beforeEach,expect,it,vi } from 'vitest';
import { createCheckpointDeps,clearFallenCharacterLifeCheckpoint,OLD_CHECKPOINT_MESSAGE,CHARACTER_LIFE_CHECKPOINT_SOCIETY_KEY,isPlayableCheckpoint,prepareCharacterLifeLoad,readLocalCharacterLife,saveLocalCharacterLife } from '../character-life-session.js';
const WORLD_NPC_CHECKPOINT_KEY = 'haven.world-npc-session.checkpoint.v1';
const WORLD_SESSION_CHECKPOINT_KEY = 'haven.world-session.checkpoint.v1';

const session = (seed = 0, currentName = 'Ana') => { const r = createCharacterLifeSession(seed, { ...structuredClone(DEFAULT_PLAYER_DRAFT), currentName }); if (!r.success) throw Error(r.error.message); return r.value; };

it('loads live and pinned v3 cities into a detached complete Life session without conversion or grants', () => {
  const oldSession = () => session();
  const decoded=deserializeCharacterLifeSave(readFileSync('packages/persistence/src/__tests__/fixtures/society-v8/life-new-game.json','utf8'));
  if(!decoded.success)throw Error(decoded.error.message);
  const fresh={success:true,value:decoded.state};
  fresh.value.city.goodsStock!.amountMilli = 321;
  for (const [live, loaded] of [[oldSession(), fresh.value], [fresh.value, oldSession()]] as const) {
    const liveBefore = structuredClone(live), loadedBefore = structuredClone(loaded);
    const result = prepareCharacterLifeLoad(live, loaded, live.city.revision);
    expect(result.success).toBe(true); if (!result.success) throw Error(result.message);
    expect({ ...result.next, city: { ...result.next.city, revision: loaded.city.revision } }).toEqual(loaded);
    result.next.city.world.settlements.settlement_haven_01.inventory.gold = 0;
    if (result.next.city.goodsStock) result.next.city.goodsStock.amountMilli = 0;
    expect(live).toEqual(liveBefore); expect(loaded).toEqual(loadedBefore);
  }
});
const otherKeys = [WORLD_NPC_CHECKPOINT_KEY, WORLD_SESSION_CHECKPOINT_KEY, 'haven.tile-trial.checkpoint.v1', 'haven.tile-population.checkpoint.v1'];
let values: Map<string, string>;
let store: GameStore;
let checkpointDeps: import('../character-life-session.js').CheckpointDeps;
let storage: { getItem: ReturnType<typeof vi.fn<(key: string) => string | null>>; setItem: ReturnType<typeof vi.fn<(key: string, value: string) => void>> };
beforeEach(() => {
  values = new Map(otherKeys.map(k => [k, 'protected-bytes']));
  storage = { getItem: vi.fn((k: string) => values.get(k) ?? null), setItem: vi.fn((k: string, v: string) => { values.set(k, v); }) };
  store = createMemoryGameStore();
  for (const key of ['read','replaceSlot','clear','getSystem'] as const) vi.spyOn(store,key);
  const atomicMigration=store.migrateSlot?.bind(store);
  Object.assign(store,{migrateSlot:vi.fn(atomicMigration)});
  checkpointDeps = { store,legacy: { getItem: storage.getItem,removeItem: vi.fn((key: string) => { values.delete(key); }) } };
});
afterEach(() => { vi.unstubAllGlobals(); vi.restoreAllMocks(); });

it('uses its own slot key', () => {
  expect(CHARACTER_LIFE_CHECKPOINT_SOCIETY_KEY).toBe('haven.character-life-session-society.checkpoint.v1');
  expect(otherKeys).not.toContain(CHARACTER_LIFE_CHECKPOINT_SOCIETY_KEY);
});
it('save writes only its key and reads back the same session; other keys keep "protected-bytes"', async () => {
  const s = session(); s.npcs[2].postTileId = 'plain-1';
  const encoded = serializeCharacterLifeSave(s); if (!encoded.success) throw Error();
  expect((await saveLocalCharacterLife(s,checkpointDeps))).toEqual({ success: true, replaced: false });
  expect(serializeCharacterLifeSave(recordsToSession((await store.read('main'))!))).toEqual(encoded);
  expect(store.replaceSlot).toHaveBeenCalledExactlyOnceWith('main',sessionToRecords('main',s));
  expect((await readLocalCharacterLife(checkpointDeps))).toEqual({ success: true, state: s });
  expect((await saveLocalCharacterLife(s,checkpointDeps))).toEqual({ success: true, replaced: true });
  otherKeys.forEach(k => expect(values.get(k)).toBe('protected-bytes'));
});
it('read with empty slot returns the "No local checkpoint" message', async () => {
  expect((await readLocalCharacterLife(checkpointDeps))).toEqual({ success: false, message: 'No local checkpoint in this browser yet. Choose Save locally first.' });
});
