it('ported F1: active Proxy saves detached descriptor data without get callbacks',async ()=>{
 const s=session();const encoded=serializeCharacterLifeSave(s);if(!encoded.success)throw Error();values.set(CHARACTER_LIFE_CHECKPOINT_SOCIETY_KEY,encoded.text);await store.replaceSlot('main',sessionToRecords('main',s));vi.mocked(store.replaceSlot).mockClear();let calls=0;
 const proxy=new Proxy(s,{get(){calls++;throw Error('private');}});
 expect((await saveLocalCharacterLife(proxy,checkpointDeps))).toEqual({success:true,replaced:true});expect(calls).toBe(0);expect(values.get(CHARACTER_LIFE_CHECKPOINT_SOCIETY_KEY)).toBe(encoded.text);expect(store.replaceSlot).toHaveBeenCalledOnce();expect(serializeCharacterLifeSave(recordsToSession((await store.read('main'))!))).toEqual(encoded);
});
it.each(['accessor','own toJSON','revoked proxy'])('ported F1: invalid %s preserves prior valid bytes before storage access',async kind=>{
 const s=session(),encoded=serializeCharacterLifeSave(s);if(!encoded.success)throw Error();values.set(CHARACTER_LIFE_CHECKPOINT_SOCIETY_KEY,encoded.text);const before=new Map(values);let calls=0;
 if(kind==='accessor')Object.defineProperty(s.city.world.settlements.settlement_haven_01.inventory,'gold',{enumerable:true,get(){calls++;return 0;}});
 if(kind==='own toJSON')Object.assign(s,{toJSON(){calls++;return {};}});
 const proxy=Proxy.revocable(s,{});if(kind==='revoked proxy')proxy.revoke();
 expect((await saveLocalCharacterLife(kind==='revoked proxy'?proxy.proxy:s,checkpointDeps)).success).toBe(false);expect(calls).toBe(0);expect(storage.getItem).not.toHaveBeenCalled();expect(store.read).not.toHaveBeenCalled();expect(store.replaceSlot).not.toHaveBeenCalled();expect(values).toEqual(before);
});
it.each(['window','getter','read','write'])('ported slot guard: %s failure preserves browser bytes and session',async kind=>{
 const s=session(),snapshot=structuredClone(s),before=new Map(values);
 if(kind==='window')vi.mocked(store.read).mockRejectedValue(Error('private'));
 if(kind==='getter')vi.mocked(store.read).mockRejectedValue(Error('private'));
 if(kind==='read')vi.mocked(store.read).mockRejectedValue(Error('private'));
 if(kind==='write')vi.mocked(store.replaceSlot).mockRejectedValue(Error('private'));
 const result=(await saveLocalCharacterLife(s,checkpointDeps));expect(result).toMatchObject({success:false,message:expect.stringContaining('Export checkpoint')});expect(JSON.stringify(result)).not.toContain('private');expect(values).toEqual(before);expect(s).toEqual(snapshot);
 if(kind!=='write')expect((await readLocalCharacterLife(checkpointDeps))).toMatchObject({success:false,message:expect.stringContaining('Import checkpoint')});
});
