// DATA-01 A2: merged cases; existing assertions above are unchanged.
const KEY = CHARACTER_LIFE_CHECKPOINT_SOCIETY_KEY;
const MARKER = 'migration:legacy-local-checkpoint';
const NONE = 'No local checkpoint in this browser yet. Choose Save locally first.';
const BLOCKED = 'Could not save in this browser (storage blocked or full). Your game and any earlier local checkpoint were preserved. Use Export checkpoint instead.';
const OLD = `Local checkpoint not loaded; it was left unchanged. ${OLD_CHECKPOINT_MESSAGE}`;
const a2Session = () => { const r = createCharacterLifeSession(0, { ...structuredClone(DEFAULT_PLAYER_DRAFT),currentName: 'Ana' }); if (!r.success) throw Error(r.error.message); return r.value; };
const a2Text = () => { const r = serializeCharacterLifeSave(a2Session()); if (!r.success) throw Error(r.error.message); return r.text; };
function deps(initial: string | null = null, opts = { failWrites: false }) {
  let value = initial;
  return { store: createMemoryGameStore(opts), legacy: { getItem: vi.fn(() => value),removeItem: vi.fn(() => { value = null; }) } };
}

it('migrates legacy once and never touches legacy on second read', async () => { const d = deps(a2Text()); vi.spyOn(d.store,'read'); expect(await readLocalCharacterLife(d)).toEqual({ success: true,state: a2Session() }); expect(d.store.read).toHaveBeenCalledExactlyOnceWith('main'); expect(await d.store.getSystem(MARKER)).not.toBeNull(); expect(await readLocalCharacterLife(d)).toEqual({ success: true,state: a2Session() }); expect(d.legacy.getItem).toHaveBeenCalledTimes(1); expect(d.legacy.removeItem).not.toHaveBeenCalled(); });
it('empty legacy writes marker', async () => { const d = deps(); expect(await readLocalCharacterLife(d)).toEqual({ success: false,message: NONE }); expect(await d.store.getSystem(MARKER)).not.toBeNull(); });
it('invalid legacy stays unchanged with existing message', async () => { const d = deps('{}'); expect(await readLocalCharacterLife(d)).toEqual({ success: false,message: OLD }); expect(d.legacy.getItem()).toBe('{}'); expect(d.legacy.removeItem).not.toHaveBeenCalled(); expect(await d.store.getSystem(MARKER)).not.toBeNull(); });
it('old ruleset legacy migrates and retains refusal message', async () => { const raw = readFileSync(new URL('../../../persistence/src/__tests__/fixtures/society-v6/life-new-game.json',import.meta.url),'utf8'); const d = deps(raw); expect(await readLocalCharacterLife(d)).toEqual({ success: false,message: OLD }); expect(await d.store.read('main')).toEqual(sessionToRecords('main',JSON.parse(raw).state)); expect(d.legacy.getItem()).toBe(raw); });
it('save and read are identical and replaced changes from false to true', async () => { const d = deps(); expect(await saveLocalCharacterLife(a2Session(),d)).toEqual({ success: true,replaced: false }); expect(await readLocalCharacterLife(d)).toEqual({ success: true,state: a2Session() }); expect(await saveLocalCharacterLife(a2Session(),d)).toEqual({ success: true,replaced: true }); });
it('failed write returns existing message and preserves records', async () => { const opts = { failWrites: false },d = deps(null,opts); await saveLocalCharacterLife(a2Session(),d); const prior = await d.store.read('main'); opts.failWrites = true; expect(await saveLocalCharacterLife(a2Session(),d)).toEqual({ success: false,message: BLOCKED }); expect(await d.store.read('main')).toEqual(prior); });
it('fallen clear keeps marker and cannot resurrect legacy', async () => { const d = deps(a2Text()); await readLocalCharacterLife(d); expect(await clearFallenCharacterLifeCheckpoint(true,'fallen',d)).toEqual({ success: true }); expect(await d.store.read('main')).toBeNull(); expect(d.legacy.removeItem).toHaveBeenCalledWith(KEY); expect(await d.store.getSystem(MARKER)).not.toBeNull(); expect(await readLocalCharacterLife(d)).toEqual({ success: false,message: NONE }); expect(d.legacy.getItem).toHaveBeenCalledTimes(1); });
it('factory failure falls back to memory with a one-time warning', async () => { const checkpointDeps = createCheckpointDeps(() => { throw Error('blocked'); },deps().legacy); expect(await readLocalCharacterLife(checkpointDeps)).toEqual({ success: false,message: BLOCKED }); expect(await readLocalCharacterLife(checkpointDeps)).toEqual({ success: false,message: NONE }); expect(await saveLocalCharacterLife(a2Session(),checkpointDeps)).toEqual({ success: true,replaced: false }); expect(await readLocalCharacterLife(checkpointDeps)).toEqual({ success: true,state: a2Session() }); });

// Raw-observable GameStore double: verifies service clears the entire slot; A3 checks real IndexedDB tables.
function inspectableDeps() {
 let rows: StoredRecord[] = [];
 const store: GameStore = {
  read: vi.fn(async (slotId: string) => {const found=rows.filter(r=>r.slotId===slotId&&r.table!=='system');return found.some(r=>r.table==='meta')?structuredClone(found):null;}),
  replaceSlot: vi.fn(async (slotId: string,next: StoredRecord[],extra: StoredRecord[] = []) => {rows=rows.filter(r=>r.slotId!==slotId&& !extra.some(e=>e.slotId===r.slotId&&e.table===r.table&&e.id===r.id));rows.push(...structuredClone([...next,...extra]));return {put:next.length,deleted:0,unchanged:0};}),
  migrateSlot: vi.fn(async (slotId: string,candidate: StoredRecord[]|null,marker: StoredRecord) => {
   const current=rows.filter(r=>r.slotId===slotId&&r.table!=='system');
   if(!rows.some(r=>r.table==='system'&&r.slotId===marker.slotId&&r.id===marker.id)){
    if(!current.some(r=>r.table==='meta')&&candidate)for(const r of structuredClone(candidate)){rows=rows.filter(old=>old.slotId!==r.slotId||old.table!==r.table||old.id!==r.id);rows.push(r);}
    rows.push(structuredClone(marker));
   }
   const result=rows.filter(r=>r.slotId===slotId&&r.table!=='system');return result.some(r=>r.table==='meta')?structuredClone(result):null;
  }),
  clear: vi.fn(async (slotId: string) => {rows=rows.filter(r=>r.slotId!==slotId||r.table==='system');}),
  getSystem: vi.fn(async (id: string) => rows.find(r=>r.table==='system'&&r.id===id)??null)
 };
 const values=new Map<string,string>();const legacy={getItem:vi.fn((key:string)=>values.get(key)??null),removeItem:vi.fn((key:string)=>{values.delete(key);})};
 return {store,legacy,values,rows:()=>structuredClone(rows)};
}
async function savedGame(d: ReturnType<typeof inspectableDeps>,seed: number) {
 const s=session(seed);expect(await readLocalCharacterLife(d)).toEqual({success:false,message:NONE});
 expect(await saveLocalCharacterLife(s,d)).toEqual({success:true,replaced:false});
 const rows=(await d.store.read('main'))!;
 await d.store.replaceSlot('main',[...rows,...(['reports','history','items'] as const).map(table=>({slotId:'main',id:'seed-'+seed,table,schemaVersion:1 as const,value:{seed}}))]);
 for(const table of GAME_DB.stores.filter(t=>t!=='system'))expect(d.rows().filter(r=>r.table===table)).not.toHaveLength(0);
 d.values.set(KEY,a2Text());
}
it('fallen clears all seven data tables and legacy; only the migration marker remains',async()=>{
 const d=inspectableDeps();await savedGame(d,11);
 expect(await clearFallenCharacterLifeCheckpoint(true,'fallen',d)).toEqual({success:true});
 for(const table of GAME_DB.stores.filter(t=>t!=='system'))expect(d.rows().filter(r=>r.slotId==='main'&&r.table===table)).toHaveLength(0);
 expect(d.legacy.removeItem).toHaveBeenCalledWith(KEY);expect(d.values.has(KEY)).toBe(false);
 expect(d.rows()).toEqual([{slotId:'_',id:MARKER,table:'system',schemaVersion:1,value:true}]);
});
it('three consecutive started saved and fallen games never accumulate records',async()=>{
 const d=inspectableDeps();const totals:number[]=[];
 for(const seed of [11,22,33]){await savedGame(d,seed);expect(await clearFallenCharacterLifeCheckpoint(true,'fallen',d)).toEqual({success:true});
  for(const table of GAME_DB.stores.filter(t=>t!=='system'))expect(d.rows().filter(r=>r.slotId==='main'&&r.table===table)).toHaveLength(0);
  expect(d.legacy.removeItem).toHaveBeenCalledTimes(totals.length+1);expect(d.values.has(KEY)).toBe(false);expect(d.rows()).toEqual([{slotId:'_',id:MARKER,table:'system',schemaVersion:1,value:true}]);totals.push(d.rows().length);
 }expect(totals).toEqual([1,1,1]);
});

it('corrupt stored city is refused with the existing message and exact records preserved',async()=>{
 const d=deps();const rows=sessionToRecords('main',a2Session());rows.find(r=>r.table==='city')!.value='{';await d.store.replaceSlot('main',rows,[{slotId:'_',id:MARKER,table:'system',schemaVersion:1,value:true}]);const before=await d.store.read('main');
 expect(await readLocalCharacterLife(d)).toEqual({success:false,message:OLD});expect(await d.store.read('main')).toEqual(before);
});

function deferred() {
 let resolve!: () => void; const promise = new Promise<void>(done => { resolve = done; });
 return { promise,resolve };
}
function holdNextRead(store: GameStore) {
 const entered=deferred(),release=deferred(),read=store.read.bind(store);
 vi.spyOn(store,'read').mockImplementationOnce(async slot=>{entered.resolve();await release.promise;return read(slot);});
 return {entered:entered.promise,release:release.resolve};
}
it('fix1 F1: pending save cannot restore records after fallen clear',async()=>{
 const d=inspectableDeps();await savedGame(d,11);const held=holdNextRead(d.store);
 const saving=saveLocalCharacterLife(session(22),d);await held.entered;
 const clearing=clearFallenCharacterLifeCheckpoint(true,'fallen',d);await Promise.resolve();held.release();
 const [saved,cleared]=await Promise.all([saving,clearing]);
 expect(await d.store.read('main')).toBeNull();
 expect(saved).toEqual({success:true,replaced:true});expect(cleared).toEqual({success:true});
 expect(d.rows()).toEqual([{slotId:'_',id:MARKER,table:'system',schemaVersion:1,value:true}]);
});
it('fix1 F1: read save and clear finish in invocation order',async()=>{
 const d=inspectableDeps();await readLocalCharacterLife(d);await saveLocalCharacterLife(session(11),d);
 const held=holdNextRead(d.store),reading=readLocalCharacterLife(d);await held.entered;
 const saving=saveLocalCharacterLife(session(22),d),clearing=clearFallenCharacterLifeCheckpoint(true,'fallen',d);
 await Promise.resolve();held.release();
 expect(await reading).toEqual({success:true,state:session(11)});expect(await saving).toEqual({success:true,replaced:true});expect(await clearing).toEqual({success:true});
 expect(d.rows()).toEqual([{slotId:'_',id:MARKER,table:'system',schemaVersion:1,value:true}]);
});
it('fix1 F1: failed checkpoint does not poison later operations',async()=>{
 const opts={failWrites:false},d=deps(null,opts);await readLocalCharacterLife(d);await saveLocalCharacterLife(session(11),d);
 opts.failWrites=true;const failed=saveLocalCharacterLife(session(22),d),reading=readLocalCharacterLife(d);
 expect(await failed).toEqual({success:false,message:BLOCKED});expect(await reading).toEqual({success:true,state:session(11)});
 opts.failWrites=false;expect(await saveLocalCharacterLife(session(33),d)).toEqual({success:true,replaced:true});expect(await readLocalCharacterLife(d)).toEqual({success:true,state:session(33)});
});
it('fix1 F1: checkpoint queue is module-wide across dependencies',async()=>{
 const first=deps(),second=deps();await readLocalCharacterLife(first);const held=holdNextRead(first.store),clear=vi.spyOn(second.store,'clear');
 const saving=saveLocalCharacterLife(session(),first);await held.entered;const clearing=clearFallenCharacterLifeCheckpoint(true,'fallen',second);
 try {await Promise.resolve();expect(clear).not.toHaveBeenCalled();}
 finally {held.release();await Promise.all([saving,clearing]);}
 expect(clear).toHaveBeenCalledExactlyOnceWith('main');
});

